"use strict";exports.id=184,exports.ids=[184],exports.modules={3184:(a,b,c)=>{c.d(b,{KB:()=>e,YZ:()=>d,Zd:()=>f});let d=[{code:"en",label:"English"},{code:"fr",label:"Fran\xe7ais"},{code:"es",label:"Espa\xf1ol"},{code:"de",label:"Deutsch"},{code:"nl",label:"Nederlands"},{code:"pt",label:"Portugu\xeas"},{code:"pl",label:"Polski"},{code:"ja",label:"日本語"},{code:"ko",label:"한국어"}],e={en:{meta:{title:"Duplicate Finder — find and reclaim duplicate files on Windows",description:"Scan any folder or drive, compare duplicates side by side with live previews, and safely move them to the Recycle Bin. €15 one-time, 14-day free trial."},nav:{howItWorks:"How it works",pricing:"Pricing",faq:"FAQ",download:"Download"},hero:{eyebrow:"For Windows \xb7 €15 one-time \xb7 14-day free trial",headlineLine1:"Find your",headlineEm:"duplicate",sub:"Scans any folder or drive, shows you exactly what's identical side by side, and moves duplicates to the Recycle Bin — never a permanent delete.",ctaPrimary:"Download for Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"See how it works",ctaNote:"Full features for 14 days. No account, no credit card.",securityNote:'First launch: Windows may show a "Windows protected your PC" prompt — this is normal for independent developers. Click More info → Run anyway.',demoMeta:"3 identical files \xb7 158.3 KB each",demoReclaimable:"158.3 KB reclaimable",counterLabel:"reclaimable, this scan",cardKeep:"Keep",cardDuplicate:"Duplicate",cardMarkForTrash:"mark for trash",cardOpenFile:"Open file ↗",cardKeepInstead:"Keep this one instead →"},howItWorks:{eyebrow:"How it works",title:"Three steps, nothing permanent until you say so.",steps:[{num:"01 — Scan",title:"Pick a folder, a drive, or your whole PC",body:"Duplicate Finder hashes every file to find exact matches — not just similar names or sizes."},{num:"02 — Compare",title:"See both copies side by side",body:"File size, modified date, and a live preview for images, PDFs, Word docs, and Excel sheets — before you decide anything."},{num:"03 — Reclaim",title:"Keep one, trash the rest",body:"Duplicates go to the Recycle Bin, never a permanent delete. Change your mind anytime."}]},features:{eyebrow:"What it does",title:"Built for actually finding duplicates, not guessing.",items:[{title:"Byte-for-byte matching",body:"Every file is hashed, so renamed or relocated copies still get caught — not just files with matching filenames."},{title:"Live previews",body:"Images, PDFs, Word documents, Excel sheets, and code files render right in the comparison view."},{title:"Recycle Bin safe",body:"Every delete goes through Windows' own Recycle Bin. Nothing is ever permanently removed by the app itself."},{title:"Scan a folder or a whole drive",body:"From one Downloads folder to your entire C:\\ drive, at whatever scope you choose."}]},pricing:{amount:"€15",terms:"One-time purchase \xb7 no subscription",list:["Full features for 14 days, free","No account or credit card for the trial","One license, yours to keep"],ctaPrimary:"Download for Windows",ctaSecondary:"Buy a license →"},faq:{eyebrow:"FAQ",title:"Before you download",items:[{q:"Will it delete files I actually need?",a:"Only files you explicitly mark, and only after you've compared them side by side. Matches are found by hashing file contents, so only true byte-for-byte duplicates ever show up — and every delete goes to the Recycle Bin, not a permanent removal."},{q:"Does it work on Mac or Linux?",a:"Not yet — Duplicate Finder is Windows-only for now."},{q:"What happens after the 14-day trial?",a:"The app locks scanning until you enter a license key. Your trial data and settings aren't affected — activating a key just unlocks it again."},{q:"Why does Windows show a warning when I install it?",a:'Because the app isn\'t yet signed with a paid code-signing certificate — something most solo developers skip before their first sales. Windows flags any unrecognized publisher this way, whether the software is safe or not; it\'s not a judgment on this specific app. Click "More info" then "Run anyway" to continue. The source code is public on GitHub if you\'d like to check what it does before installing.'}]},footer:{copyright:"Duplicate Finder.",changelog:"Changelog",buy:"Buy",privacy:"Privacy",terms:"Terms"}},fr:{meta:{title:"Duplicate Finder — trouvez et r\xe9cup\xe9rez l'espace de vos fichiers en double sur Windows",description:"Analysez n'importe quel dossier ou disque, comparez les doublons c\xf4te \xe0 c\xf4te avec un aper\xe7u en direct, et d\xe9placez-les en toute s\xe9curit\xe9 vers la corbeille. 15 € en une fois, essai gratuit de 14 jours."},nav:{howItWorks:"Fonctionnement",pricing:"Tarif",faq:"FAQ",download:"T\xe9l\xe9charger"},hero:{eyebrow:"Pour Windows \xb7 15 € en une fois \xb7 Essai gratuit de 14 jours",headlineLine1:"Trouvez vos fichiers en",headlineEm:"double",sub:"Analyse n'importe quel dossier ou disque, vous montre exactement ce qui est identique c\xf4te \xe0 c\xf4te, et d\xe9place les doublons vers la corbeille — jamais de suppression d\xe9finitive.",ctaPrimary:"T\xe9l\xe9charger pour Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"Voir comment \xe7a marche",ctaNote:"Toutes les fonctionnalit\xe9s pendant 14 jours. Sans compte, sans carte bancaire.",securityNote:"Premier lancement : Windows peut afficher un message \xab Windows a prot\xe9g\xe9 votre ordinateur \xbb — c'est normal pour les d\xe9veloppeurs ind\xe9pendants. Cliquez sur \xab Plus d'infos \xbb → \xab Ex\xe9cuter quand m\xeame \xbb.",demoMeta:"3 fichiers identiques \xb7 158,3 Ko chacun",demoReclaimable:"158,3 Ko r\xe9cup\xe9rables",counterLabel:"r\xe9cup\xe9rables sur cette analyse",cardKeep:"Conserver",cardDuplicate:"Doublon",cardMarkForTrash:"marquer pour la corbeille",cardOpenFile:"Ouvrir le fichier ↗",cardKeepInstead:"Conserver celui-ci \xe0 la place →"},howItWorks:{eyebrow:"Fonctionnement",title:"Trois \xe9tapes, rien n'est d\xe9finitif tant que vous ne le d\xe9cidez pas.",steps:[{num:"01 — Analyser",title:"Choisissez un dossier, un disque, ou tout votre PC",body:"Duplicate Finder hache chaque fichier pour trouver des correspondances exactes — pas seulement des noms ou des tailles similaires."},{num:"02 — Comparer",title:"Visualisez les deux copies c\xf4te \xe0 c\xf4te",body:"Taille du fichier, date de modification, et un aper\xe7u en direct pour les images, PDF, documents Word et feuilles Excel — avant toute d\xe9cision."},{num:"03 — R\xe9cup\xe9rer",title:"Gardez-en un, supprimez le reste",body:"Les doublons vont dans la corbeille, jamais de suppression d\xe9finitive. Vous pouvez toujours changer d'avis."}]},features:{eyebrow:"Fonctionnalit\xe9s",title:"Con\xe7u pour vraiment trouver les doublons, pas pour deviner.",items:[{title:"Correspondance octet par octet",body:"Chaque fichier est hach\xe9, donc les copies renomm\xe9es ou d\xe9plac\xe9es sont quand m\xeame d\xe9tect\xe9es — pas seulement les fichiers avec des noms identiques."},{title:"Aper\xe7us en direct",body:"Images, PDF, documents Word, feuilles Excel et fichiers de code s'affichent directement dans la vue de comparaison."},{title:"S\xe9curis\xe9 par la corbeille",body:"Chaque suppression passe par la corbeille de Windows. Rien n'est jamais supprim\xe9 d\xe9finitivement par l'application elle-m\xeame."},{title:"Analysez un dossier ou un disque entier",body:"D'un simple dossier T\xe9l\xe9chargements jusqu'\xe0 tout votre disque C:\\, selon la port\xe9e que vous choisissez."}]},pricing:{amount:"15 €",terms:"Achat unique \xb7 sans abonnement",list:["Toutes les fonctionnalit\xe9s pendant 14 jours, gratuitement","Aucun compte ni carte bancaire pour l'essai","Une licence, \xe0 vous pour toujours"],ctaPrimary:"T\xe9l\xe9charger pour Windows",ctaSecondary:"Acheter une licence →"},faq:{eyebrow:"FAQ",title:"Avant de t\xe9l\xe9charger",items:[{q:"Va-t-il supprimer des fichiers dont j'ai besoin ?",a:"Seulement les fichiers que vous marquez explicitement, et seulement apr\xe8s les avoir compar\xe9s c\xf4te \xe0 c\xf4te. Les correspondances sont trouv\xe9es en hachant le contenu des fichiers, donc seuls les vrais doublons octet par octet apparaissent — et chaque suppression va dans la corbeille, jamais d\xe9finitive."},{q:"Fonctionne-t-il sur Mac ou Linux ?",a:"Pas encore — Duplicate Finder est uniquement disponible sur Windows pour le moment."},{q:"Que se passe-t-il apr\xe8s l'essai de 14 jours ?",a:"L'application bloque l'analyse jusqu'\xe0 ce que vous saisissiez une cl\xe9 de licence. Vos donn\xe9es et param\xe8tres d'essai ne sont pas affect\xe9s — activer une cl\xe9 d\xe9bloque simplement l'application \xe0 nouveau."},{q:"Pourquoi Windows affiche-t-il un avertissement \xe0 l'installation ?",a:"Parce que l'application n'est pas encore sign\xe9e avec un certificat payant — une \xe9tape que la plupart des d\xe9veloppeurs ind\xe9pendants sautent avant leurs premi\xe8res ventes. Windows affiche ce message pour tout \xe9diteur non reconnu, que le logiciel soit s\xfbr ou non ; ce n'est pas un jugement sur cette application en particulier. Cliquez sur \xab Plus d'infos \xbb puis \xab Ex\xe9cuter quand m\xeame \xbb pour continuer. Le code source est public sur GitHub si vous souhaitez v\xe9rifier ce qu'elle fait avant d'installer."}]},footer:{copyright:"Duplicate Finder.",changelog:"Journal des modifications",buy:"Acheter",privacy:"Confidentialit\xe9",terms:"Conditions"}},es:{meta:{title:"Duplicate Finder — encuentra y recupera espacio de archivos duplicados en Windows",description:"Analice cualquier carpeta o unidad, compare duplicados uno junto al otro con vista previa en vivo, y mu\xe9valos de forma segura a la papelera de reciclaje. 15 € pago \xfanico, prueba gratuita de 14 d\xedas."},nav:{howItWorks:"C\xf3mo funciona",pricing:"Precio",faq:"Preguntas frecuentes",download:"Descargar"},hero:{eyebrow:"Para Windows \xb7 15 € pago \xfanico \xb7 Prueba gratuita de 14 d\xedas",headlineLine1:"Encuentre sus archivos",headlineEm:"duplicados",sub:"Analiza cualquier carpeta o unidad, le muestra exactamente qu\xe9 es id\xe9ntico uno junto al otro, y mueve los duplicados a la papelera de reciclaje — nunca una eliminaci\xf3n permanente.",ctaPrimary:"Descargar para Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"Ver c\xf3mo funciona",ctaNote:"Todas las funciones durante 14 d\xedas. Sin cuenta, sin tarjeta de cr\xe9dito.",securityNote:"Primer inicio: Windows puede mostrar un aviso \xabWindows protegi\xf3 su equipo\xbb — esto es normal para desarrolladores independientes. Haga clic en \xabM\xe1s informaci\xf3n\xbb → \xabEjecutar de todos modos\xbb.",demoMeta:"3 archivos id\xe9nticos \xb7 158,3 KB cada uno",demoReclaimable:"158,3 KB recuperables",counterLabel:"recuperables en este an\xe1lisis",cardKeep:"Conservar",cardDuplicate:"Duplicado",cardMarkForTrash:"marcar para la papelera",cardOpenFile:"Abrir archivo ↗",cardKeepInstead:"Conservar este en su lugar →"},howItWorks:{eyebrow:"C\xf3mo funciona",title:"Tres pasos, nada permanente hasta que usted lo decida.",steps:[{num:"01 — Analizar",title:"Elija una carpeta, una unidad o todo su PC",body:"Duplicate Finder procesa cada archivo para encontrar coincidencias exactas — no solo nombres o tama\xf1os similares."},{num:"02 — Comparar",title:"Vea ambas copias una junto a la otra",body:"Tama\xf1o del archivo, fecha de modificaci\xf3n y una vista previa en vivo para im\xe1genes, PDF, documentos de Word y hojas de Excel — antes de decidir nada."},{num:"03 — Recuperar",title:"Conserve uno, elimine el resto",body:"Los duplicados van a la papelera de reciclaje, nunca una eliminaci\xf3n permanente. Puede cambiar de opini\xf3n en cualquier momento."}]},features:{eyebrow:"Qu\xe9 hace",title:"Dise\xf1ado para encontrar duplicados de verdad, no para adivinar.",items:[{title:"Coincidencia byte por byte",body:"Cada archivo se procesa con hash, as\xed que las copias renombradas o movidas igual se detectan — no solo archivos con nombres coincidentes."},{title:"Vistas previas en vivo",body:"Im\xe1genes, PDF, documentos de Word, hojas de Excel y archivos de c\xf3digo se muestran directamente en la vista de comparaci\xf3n."},{title:"Seguro con la papelera de reciclaje",body:"Cada eliminaci\xf3n pasa por la papelera de reciclaje de Windows. La aplicaci\xf3n nunca elimina nada de forma permanente por s\xed misma."},{title:"Analice una carpeta o una unidad completa",body:"Desde una sola carpeta de Descargas hasta toda su unidad C:\\, con el alcance que usted elija."}]},pricing:{amount:"15 €",terms:"Compra \xfanica \xb7 sin suscripci\xf3n",list:["Todas las funciones durante 14 d\xedas, gratis","Sin cuenta ni tarjeta de cr\xe9dito para la prueba","Una licencia, suya para siempre"],ctaPrimary:"Descargar para Windows",ctaSecondary:"Comprar una licencia →"},faq:{eyebrow:"Preguntas frecuentes",title:"Antes de descargar",items:[{q:"\xbfEliminar\xe1 archivos que realmente necesito?",a:"Solo los archivos que marque expl\xedcitamente, y solo despu\xe9s de haberlos comparado uno junto al otro. Las coincidencias se encuentran mediante el hash del contenido de los archivos, as\xed que solo aparecen duplicados reales byte por byte — y cada eliminaci\xf3n va a la papelera de reciclaje, nunca es permanente."},{q:"\xbfFunciona en Mac o Linux?",a:"Todav\xeda no — Duplicate Finder es exclusivo de Windows por ahora."},{q:"\xbfQu\xe9 pasa despu\xe9s de la prueba de 14 d\xedas?",a:"La aplicaci\xf3n bloquea el an\xe1lisis hasta que introduzca una clave de licencia. Sus datos y configuraci\xf3n de prueba no se ven afectados — activar una clave simplemente la desbloquea de nuevo."},{q:"\xbfPor qu\xe9 Windows muestra una advertencia al instalarlo?",a:"Porque la aplicaci\xf3n a\xfan no est\xe1 firmada con un certificado de firma de c\xf3digo de pago — algo que la mayor\xeda de los desarrolladores independientes omiten antes de sus primeras ventas. Windows marca as\xed a cualquier editor no reconocido, sea o no seguro el software; no es un juicio sobre esta aplicaci\xf3n en particular. Haga clic en \xabM\xe1s informaci\xf3n\xbb y luego en \xabEjecutar de todos modos\xbb para continuar. El c\xf3digo fuente es p\xfablico en GitHub si desea comprobar qu\xe9 hace antes de instalarlo."}]},footer:{copyright:"Duplicate Finder.",changelog:"Registro de cambios",buy:"Comprar",privacy:"Privacidad",terms:"T\xe9rminos"}},de:{meta:{title:"Duplicate Finder — doppelte Dateien unter Windows finden und Speicherplatz zur\xfcckgewinnen",description:"Durchsuchen Sie beliebige Ordner oder Laufwerke, vergleichen Sie Duplikate nebeneinander mit Live-Vorschau und verschieben Sie sie sicher in den Papierkorb. 15 € einmalig, 14 Tage kostenlos testen."},nav:{howItWorks:"So funktioniert's",pricing:"Preis",faq:"FAQ",download:"Herunterladen"},hero:{eyebrow:"F\xfcr Windows \xb7 15 € einmalig \xb7 14 Tage kostenlos testen",headlineLine1:"Finden Sie Ihre",headlineEm:"doppelten",sub:"Durchsucht beliebige Ordner oder Laufwerke, zeigt Ihnen genau, was identisch ist, nebeneinander, und verschiebt Duplikate in den Papierkorb — niemals dauerhaft gel\xf6scht.",ctaPrimary:"F\xfcr Windows herunterladen",ctaStore:"Get it from Microsoft Store",ctaSecondary:"So funktioniert's",ctaNote:"Alle Funktionen f\xfcr 14 Tage. Kein Konto, keine Kreditkarte.",securityNote:'Erster Start: Windows zeigt m\xf6glicherweise die Meldung „Windows hat Ihren PC gesch\xfctzt" — das ist normal bei unabh\xe4ngigen Entwicklern. Klicken Sie auf „Weitere Informationen" → „Trotzdem ausf\xfchren".',demoMeta:"3 identische Dateien \xb7 je 158,3 KB",demoReclaimable:"158,3 KB wiederherstellbar",counterLabel:"wiederherstellbar bei diesem Scan",cardKeep:"Behalten",cardDuplicate:"Duplikat",cardMarkForTrash:"f\xfcr den Papierkorb markieren",cardOpenFile:"Datei \xf6ffnen ↗",cardKeepInstead:"Stattdessen diese behalten →"},howItWorks:{eyebrow:"So funktioniert's",title:"Drei Schritte, nichts ist endg\xfcltig, bis Sie es entscheiden.",steps:[{num:"01 — Scannen",title:"W\xe4hlen Sie einen Ordner, ein Laufwerk oder den ganzen PC",body:"Duplicate Finder hasht jede Datei, um exakte \xdcbereinstimmungen zu finden — nicht nur \xe4hnliche Namen oder Gr\xf6\xdfen."},{num:"02 — Vergleichen",title:"Beide Kopien nebeneinander ansehen",body:"Dateigr\xf6\xdfe, \xc4nderungsdatum und eine Live-Vorschau f\xfcr Bilder, PDFs, Word-Dokumente und Excel-Tabellen — bevor Sie etwas entscheiden."},{num:"03 — Zur\xfcckgewinnen",title:"Eine behalten, den Rest l\xf6schen",body:"Duplikate wandern in den Papierkorb, niemals eine dauerhafte L\xf6schung. Sie k\xf6nnen es sich jederzeit anders \xfcberlegen."}]},features:{eyebrow:"Was es kann",title:"Entwickelt, um Duplikate wirklich zu finden, nicht zu raten.",items:[{title:"Byte-genauer Abgleich",body:"Jede Datei wird gehasht, sodass umbenannte oder verschobene Kopien trotzdem erkannt werden — nicht nur Dateien mit \xfcbereinstimmenden Namen."},{title:"Live-Vorschauen",body:"Bilder, PDFs, Word-Dokumente, Excel-Tabellen und Code-Dateien werden direkt in der Vergleichsansicht angezeigt."},{title:"Sicher \xfcber den Papierkorb",body:"Jede L\xf6schung l\xe4uft \xfcber den Windows-Papierkorb. Die App selbst l\xf6scht niemals etwas dauerhaft."},{title:"Ordner oder ganzes Laufwerk scannen",body:"Von einem einzelnen Downloads-Ordner bis zum gesamten Laufwerk C:\\ — in dem Umfang, den Sie w\xe4hlen."}]},pricing:{amount:"15 €",terms:"Einmalkauf \xb7 kein Abonnement",list:["Alle Funktionen 14 Tage lang kostenlos","Kein Konto oder Kreditkarte f\xfcr die Testversion n\xf6tig","Eine Lizenz, dauerhaft Ihre"],ctaPrimary:"F\xfcr Windows herunterladen",ctaSecondary:"Lizenz kaufen →"},faq:{eyebrow:"FAQ",title:"Bevor Sie herunterladen",items:[{q:"Werden Dateien gel\xf6scht, die ich tats\xe4chlich brauche?",a:"Nur Dateien, die Sie ausdr\xfccklich markieren, und nur nachdem Sie sie nebeneinander verglichen haben. \xdcbereinstimmungen werden durch das Hashen des Dateiinhalts gefunden, sodass nur echte, byte-genaue Duplikate angezeigt werden — und jede L\xf6schung geht in den Papierkorb, keine dauerhafte Entfernung."},{q:"Funktioniert es auf Mac oder Linux?",a:"Noch nicht — Duplicate Finder ist vorerst nur f\xfcr Windows verf\xfcgbar."},{q:"Was passiert nach der 14-t\xe4gigen Testphase?",a:"Die App sperrt das Scannen, bis Sie einen Lizenzschl\xfcssel eingeben. Ihre Testdaten und Einstellungen bleiben unber\xfchrt — die Aktivierung eines Schl\xfcssels schaltet die App einfach wieder frei."},{q:"Warum zeigt Windows bei der Installation eine Warnung an?",a:'Weil die App noch nicht mit einem kostenpflichtigen Code-Signing-Zertifikat signiert ist — ein Schritt, den die meisten Solo-Entwickler vor ihren ersten Verk\xe4ufen auslassen. Windows markiert damit jeden unbekannten Herausgeber, unabh\xe4ngig davon, ob die Software sicher ist; es ist kein Urteil \xfcber diese spezielle App. Klicken Sie auf „Weitere Informationen" und dann „Trotzdem ausf\xfchren", um fortzufahren. Der Quellcode ist \xf6ffentlich auf GitHub einsehbar, falls Sie vor der Installation pr\xfcfen m\xf6chten, was die App tut.'}]},footer:{copyright:"Duplicate Finder.",changelog:"\xc4nderungsprotokoll",buy:"Kaufen",privacy:"Datenschutz",terms:"AGB"}},nl:{meta:{title:"Duplicate Finder — dubbele bestanden vinden en ruimte terugwinnen op Windows",description:"Scan elke map of schijf, vergelijk duplicaten naast elkaar met live voorbeeld, en verplaats ze veilig naar de prullenbak. €15 eenmalig, 14 dagen gratis proberen."},nav:{howItWorks:"Hoe het werkt",pricing:"Prijs",faq:"Veelgestelde vragen",download:"Downloaden"},hero:{eyebrow:"Voor Windows \xb7 €15 eenmalig \xb7 14 dagen gratis proberen",headlineLine1:"Vind uw",headlineEm:"dubbele",sub:"Scant elke map of schijf, toont u precies wat identiek is naast elkaar, en verplaatst duplicaten naar de prullenbak — nooit permanent verwijderd.",ctaPrimary:"Downloaden voor Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"Bekijk hoe het werkt",ctaNote:"Alle functies 14 dagen lang. Geen account, geen creditcard.",securityNote:'Eerste keer opstarten: Windows kan de melding "Windows heeft uw pc beschermd" tonen — dit is normaal voor onafhankelijke ontwikkelaars. Klik op "Meer info" → "Toch uitvoeren".',demoMeta:"3 identieke bestanden \xb7 elk 158,3 KB",demoReclaimable:"158,3 KB terug te winnen",counterLabel:"terug te winnen bij deze scan",cardKeep:"Behouden",cardDuplicate:"Duplicaat",cardMarkForTrash:"markeren voor prullenbak",cardOpenFile:"Bestand openen ↗",cardKeepInstead:"Dit bestand behouden in plaats daarvan →"},howItWorks:{eyebrow:"Hoe het werkt",title:"Drie stappen, niets is definitief totdat u dat beslist.",steps:[{num:"01 — Scannen",title:"Kies een map, een schijf, of uw hele pc",body:"Duplicate Finder hasht elk bestand om exacte overeenkomsten te vinden — niet alleen vergelijkbare namen of groottes."},{num:"02 — Vergelijken",title:"Bekijk beide kopie\xebn naast elkaar",body:"Bestandsgrootte, wijzigingsdatum en een live voorbeeld voor afbeeldingen, pdf's, Word-documenten en Excel-bladen — voordat u iets beslist."},{num:"03 — Terugwinnen",title:"Behoud er \xe9\xe9n, verwijder de rest",body:"Duplicaten gaan naar de prullenbak, nooit permanent verwijderd. U kunt altijd van gedachten veranderen."}]},features:{eyebrow:"Wat het doet",title:"Gemaakt om duplicaten echt te vinden, niet te gokken.",items:[{title:"Byte-voor-byte vergelijking",body:"Elk bestand wordt gehasht, zodat hernoemde of verplaatste kopie\xebn alsnog worden gevonden — niet alleen bestanden met dezelfde naam."},{title:"Live voorbeelden",body:"Afbeeldingen, pdf's, Word-documenten, Excel-bladen en codebestanden worden direct weergegeven in de vergelijkingsweergave."},{title:"Veilig via de prullenbak",body:"Elke verwijdering verloopt via de Windows-prullenbak. De app zelf verwijdert nooit iets permanent."},{title:"Scan een map of een hele schijf",body:"Van \xe9\xe9n Downloads-map tot uw hele C:\\-schijf, met de reikwijdte die u kiest."}]},pricing:{amount:"€15",terms:"Eenmalige aankoop \xb7 geen abonnement",list:["Alle functies 14 dagen lang, gratis","Geen account of creditcard nodig voor de proefperiode","E\xe9n licentie, voorgoed van u"],ctaPrimary:"Downloaden voor Windows",ctaSecondary:"Licentie kopen →"},faq:{eyebrow:"Veelgestelde vragen",title:"Voordat u downloadt",items:[{q:"Worden er bestanden verwijderd die ik echt nodig heb?",a:"Alleen bestanden die u expliciet markeert, en pas nadat u ze naast elkaar heeft vergeleken. Overeenkomsten worden gevonden door de inhoud van bestanden te hashen, dus alleen echte, byte-voor-byte duplicaten verschijnen — en elke verwijdering gaat naar de prullenbak, nooit permanent."},{q:"Werkt het op Mac of Linux?",a:"Nog niet — Duplicate Finder is voorlopig alleen beschikbaar voor Windows."},{q:"Wat gebeurt er na de proefperiode van 14 dagen?",a:"De app blokkeert scannen totdat u een licentiesleutel invoert. Uw proefgegevens en instellingen blijven ongewijzigd — het activeren van een sleutel ontgrendelt de app gewoon weer."},{q:"Waarom toont Windows een waarschuwing bij installatie?",a:'Omdat de app nog niet is ondertekend met een betaald code-signing certificaat — een stap die de meeste zelfstandige ontwikkelaars overslaan v\xf3\xf3r hun eerste verkopen. Windows markeert zo elke onbekende uitgever, ongeacht of de software veilig is; het is geen oordeel over deze specifieke app. Klik op "Meer info" en vervolgens op "Toch uitvoeren" om door te gaan. De broncode is openbaar op GitHub als u wilt controleren wat de app doet v\xf3\xf3r installatie.'}]},footer:{copyright:"Duplicate Finder.",changelog:"Wijzigingslogboek",buy:"Kopen",privacy:"Privacy",terms:"Voorwaarden"}},pt:{meta:{title:"Duplicate Finder — encontre e recupere espa\xe7o de arquivos duplicados no Windows",description:"Analise qualquer pasta ou unidade, compare duplicatas lado a lado com pr\xe9-visualiza\xe7\xe3o ao vivo, e mova-as com seguran\xe7a para a lixeira. €15 pagamento \xfanico, teste gr\xe1tis de 14 dias."},nav:{howItWorks:"Como funciona",pricing:"Pre\xe7o",faq:"Perguntas frequentes",download:"Baixar"},hero:{eyebrow:"Para Windows \xb7 €15 pagamento \xfanico \xb7 Teste gr\xe1tis de 14 dias",headlineLine1:"Encontre seus arquivos",headlineEm:"duplicados",sub:"Analisa qualquer pasta ou unidade, mostra exatamente o que \xe9 id\xeantico lado a lado, e move duplicatas para a lixeira — nunca uma exclus\xe3o permanente.",ctaPrimary:"Baixar para Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"Ver como funciona",ctaNote:"Todos os recursos por 14 dias. Sem conta, sem cart\xe3o de cr\xe9dito.",securityNote:'Primeira execu\xe7\xe3o: o Windows pode exibir um aviso "O Windows protegeu o computador" — isso \xe9 normal para desenvolvedores independentes. Clique em "Mais informa\xe7\xf5es" → "Executar assim mesmo".',demoMeta:"3 arquivos id\xeanticos \xb7 158,3 KB cada",demoReclaimable:"158,3 KB recuper\xe1veis",counterLabel:"recuper\xe1veis nesta an\xe1lise",cardKeep:"Manter",cardDuplicate:"Duplicata",cardMarkForTrash:"marcar para a lixeira",cardOpenFile:"Abrir arquivo ↗",cardKeepInstead:"Manter este em vez disso →"},howItWorks:{eyebrow:"Como funciona",title:"Tr\xeas passos, nada \xe9 permanente at\xe9 voc\xea decidir.",steps:[{num:"01 — Analisar",title:"Escolha uma pasta, uma unidade ou todo o seu PC",body:"O Duplicate Finder processa cada arquivo para encontrar correspond\xeancias exatas — n\xe3o apenas nomes ou tamanhos semelhantes."},{num:"02 — Comparar",title:"Veja as duas c\xf3pias lado a lado",body:"Tamanho do arquivo, data de modifica\xe7\xe3o e uma pr\xe9-visualiza\xe7\xe3o ao vivo para imagens, PDFs, documentos Word e planilhas Excel — antes de decidir qualquer coisa."},{num:"03 — Recuperar",title:"Mantenha um, exclua o resto",body:"As duplicatas v\xe3o para a lixeira, nunca uma exclus\xe3o permanente. Voc\xea pode mudar de ideia a qualquer momento."}]},features:{eyebrow:"O que ele faz",title:"Criado para realmente encontrar duplicatas, n\xe3o adivinhar.",items:[{title:"Correspond\xeancia byte a byte",body:"Cada arquivo \xe9 processado com hash, ent\xe3o c\xf3pias renomeadas ou movidas ainda s\xe3o detectadas — n\xe3o apenas arquivos com nomes correspondentes."},{title:"Pr\xe9-visualiza\xe7\xf5es ao vivo",body:"Imagens, PDFs, documentos Word, planilhas Excel e arquivos de c\xf3digo s\xe3o exibidos diretamente na visualiza\xe7\xe3o de compara\xe7\xe3o."},{title:"Seguro com a lixeira",body:"Cada exclus\xe3o passa pela lixeira do pr\xf3prio Windows. O aplicativo nunca remove nada permanentemente por conta pr\xf3pria."},{title:"Analise uma pasta ou uma unidade inteira",body:"De uma \xfanica pasta de Downloads at\xe9 toda a sua unidade C:\\, no escopo que voc\xea escolher."}]},pricing:{amount:"€15",terms:"Compra \xfanica \xb7 sem assinatura",list:["Todos os recursos por 14 dias, gr\xe1tis","Sem conta ou cart\xe3o de cr\xe9dito para o teste","Uma licen\xe7a, sua para sempre"],ctaPrimary:"Baixar para Windows",ctaSecondary:"Comprar uma licen\xe7a →"},faq:{eyebrow:"Perguntas frequentes",title:"Antes de baixar",items:[{q:"Ele vai excluir arquivos que eu realmente preciso?",a:"Somente arquivos que voc\xea marcar explicitamente, e somente depois de compar\xe1-los lado a lado. As correspond\xeancias s\xe3o encontradas processando o conte\xfado dos arquivos com hash, ent\xe3o apenas duplicatas reais, byte a byte, aparecem — e cada exclus\xe3o vai para a lixeira, nunca \xe9 uma remo\xe7\xe3o permanente."},{q:"Funciona no Mac ou Linux?",a:"Ainda n\xe3o — o Duplicate Finder \xe9 exclusivo para Windows por enquanto."},{q:"O que acontece ap\xf3s o teste de 14 dias?",a:"O aplicativo bloqueia a an\xe1lise at\xe9 que voc\xea insira uma chave de licen\xe7a. Seus dados e configura\xe7\xf5es do teste n\xe3o s\xe3o afetados — ativar uma chave apenas desbloqueia o aplicativo novamente."},{q:"Por que o Windows exibe um aviso ao instalar?",a:'Porque o aplicativo ainda n\xe3o est\xe1 assinado com um certificado de assinatura de c\xf3digo pago — uma etapa que a maioria dos desenvolvedores independentes pula antes das primeiras vendas. O Windows sinaliza assim qualquer editor n\xe3o reconhecido, seja o software seguro ou n\xe3o; n\xe3o \xe9 um julgamento sobre este aplicativo em particular. Clique em "Mais informa\xe7\xf5es" e depois em "Executar assim mesmo" para continuar. O c\xf3digo-fonte \xe9 p\xfablico no GitHub, caso queira verificar o que ele faz antes de instalar.'}]},footer:{copyright:"Duplicate Finder.",changelog:"Registro de altera\xe7\xf5es",buy:"Comprar",privacy:"Privacidade",terms:"Termos"}},pl:{meta:{title:"Duplicate Finder — znajdź duplikaty plik\xf3w i odzyskaj miejsce na Windows",description:"Skanuj dowolny folder lub dysk, por\xf3wnuj duplikaty obok siebie z podglądem na żywo i bezpiecznie przenoś je do kosza. 15 € jednorazowo, 14-dniowy bezpłatny okres pr\xf3bny."},nav:{howItWorks:"Jak to działa",pricing:"Cena",faq:"FAQ",download:"Pobierz"},hero:{eyebrow:"Dla Windows \xb7 15 € jednorazowo \xb7 14-dniowy bezpłatny okres pr\xf3bny",headlineLine1:"Znajdź swoje",headlineEm:"duplikaty",sub:"Skanuje dowolny folder lub dysk, pokazuje dokładnie, co jest identyczne, obok siebie, i przenosi duplikaty do kosza — nigdy trwałe usunięcie.",ctaPrimary:"Pobierz dla Windows",ctaStore:"Get it from Microsoft Store",ctaSecondary:"Zobacz, jak to działa",ctaNote:"Wszystkie funkcje przez 14 dni. Bez konta, bez karty kredytowej.",securityNote:'Pierwsze uruchomienie: Windows może wyświetlić komunikat „Windows chronił Tw\xf3j komputer" — to normalne u niezależnych deweloper\xf3w. Kliknij „Więcej informacji" → „Uruchom mimo to".',demoMeta:"3 identyczne pliki \xb7 po 158,3 KB",demoReclaimable:"158,3 KB do odzyskania",counterLabel:"do odzyskania w tym skanowaniu",cardKeep:"Zachowaj",cardDuplicate:"Duplikat",cardMarkForTrash:"zaznacz do kosza",cardOpenFile:"Otw\xf3rz plik ↗",cardKeepInstead:"Zachowaj ten zamiast tego →"},howItWorks:{eyebrow:"Jak to działa",title:"Trzy kroki, nic nie jest trwałe, dop\xf3ki tego nie zdecydujesz.",steps:[{num:"01 — Skanuj",title:"Wybierz folder, dysk lub cały komputer",body:"Duplicate Finder haszuje każdy plik, aby znaleźć dokładne dopasowania — nie tylko podobne nazwy czy rozmiary."},{num:"02 — Por\xf3wnaj",title:"Zobacz obie kopie obok siebie",body:"Rozmiar pliku, data modyfikacji i podgląd na żywo dla obraz\xf3w, plik\xf3w PDF, dokument\xf3w Word i arkuszy Excel — zanim cokolwiek zdecydujesz."},{num:"03 — Odzyskaj",title:"Zachowaj jeden, usuń resztę",body:"Duplikaty trafiają do kosza, nigdy trwałe usunięcie. Możesz zmienić zdanie w każdej chwili."}]},features:{eyebrow:"Co potrafi",title:"Zbudowany, by naprawdę znajdować duplikaty, a nie zgadywać.",items:[{title:"Dopasowanie bajt po bajcie",body:"Każdy plik jest haszowany, więc zmienione nazwy lub przeniesione kopie i tak zostaną wykryte — nie tylko pliki o pasujących nazwach."},{title:"Podglądy na żywo",body:"Obrazy, pliki PDF, dokumenty Word, arkusze Excel i pliki kodu są wyświetlane bezpośrednio w widoku por\xf3wnania."},{title:"Bezpieczne dzięki koszowi",body:"Każde usunięcie przechodzi przez kosz systemu Windows. Aplikacja sama w sobie nigdy niczego trwale nie usuwa."},{title:"Skanuj folder lub cały dysk",body:"Od jednego folderu Pobrane po cały dysk C:\\, w zakresie, kt\xf3ry wybierzesz."}]},pricing:{amount:"15 €",terms:"Jednorazowy zakup \xb7 bez subskrypcji",list:["Wszystkie funkcje przez 14 dni, za darmo","Brak konta lub karty kredytowej na okres pr\xf3bny","Jedna licencja, na zawsze twoja"],ctaPrimary:"Pobierz dla Windows",ctaSecondary:"Kup licencję →"},faq:{eyebrow:"FAQ",title:"Zanim pobierzesz",items:[{q:"Czy usunie pliki, kt\xf3rych naprawdę potrzebuję?",a:"Tylko pliki, kt\xf3re wyraźnie oznaczysz, i tylko po ich por\xf3wnaniu obok siebie. Dopasowania znajdowane są przez haszowanie zawartości plik\xf3w, więc pojawiają się tylko prawdziwe duplikaty bajt po bajcie — a każde usunięcie trafia do kosza, nigdy nie jest trwałe."},{q:"Czy działa na Mac lub Linux?",a:"Jeszcze nie — Duplicate Finder jest na razie dostępny tylko dla Windows."},{q:"Co się dzieje po 14-dniowym okresie pr\xf3bnym?",a:"Aplikacja blokuje skanowanie, dop\xf3ki nie wprowadzisz klucza licencyjnego. Twoje dane i ustawienia z okresu pr\xf3bnego pozostają nienaruszone — aktywacja klucza po prostu ponownie odblokowuje aplikację."},{q:"Dlaczego Windows wyświetla ostrzeżenie podczas instalacji?",a:'Ponieważ aplikacja nie jest jeszcze podpisana płatnym certyfikatem podpisywania kodu — krok, kt\xf3ry większość niezależnych deweloper\xf3w pomija przed pierwszą sprzedażą. Windows w ten spos\xf3b oznacza każdego nierozpoznanego wydawcę, niezależnie od tego, czy oprogramowanie jest bezpieczne; to nie jest ocena akurat tej aplikacji. Kliknij „Więcej informacji", a następnie „Uruchom mimo to", aby kontynuować. Kod źr\xf3dłowy jest publicznie dostępny na GitHub, jeśli chcesz sprawdzić, co robi przed instalacją.'}]},footer:{copyright:"Duplicate Finder.",changelog:"Historia zmian",buy:"Kup",privacy:"Prywatność",terms:"Regulamin"}},ja:{meta:{title:"Duplicate Finder — Windows で重複ファイルを見つけて容量を解放",description:"任意のフォルダーやドライブをスキャンし、重複ファイルをライブプレビュー付きで比較して、安全にごみ箱に移動できます。買い切り15ユーロ、14日間無料体験。"},nav:{howItWorks:"使い方",pricing:"料金",faq:"よくある質問",download:"ダウンロード"},hero:{eyebrow:"Windows 対応 \xb7 買い切り15ユーロ \xb7 14日間無料体験",headlineLine1:"見つけよう、あなたの",headlineEm:"重複ファイル",sub:"任意のフォルダーやドライブをスキャンし、同一のファイルを並べて正確に表示し、重複ファイルをごみ箱に移動します — 完全な削除は行いません。",ctaPrimary:"Windows版をダウンロード",ctaStore:"Get it from Microsoft Store",ctaSecondary:"使い方を見る",ctaNote:"14日間、すべての機能を利用可能。アカウント登録・クレジットカード不要。",securityNote:"初回起動時：Windows が「Windows によって PC が保護されました」と表示することがあります — これは独立系開発者のアプリではよくあることです。「詳細情報」→「実行」をクリックしてください。",demoMeta:"同一ファイル3件・各158.3 KB",demoReclaimable:"158.3 KB 解放可能",counterLabel:"このスキャンで解放可能",cardKeep:"保持",cardDuplicate:"重複",cardMarkForTrash:"ごみ箱に入れる対象としてマーク",cardOpenFile:"ファイルを開く ↗",cardKeepInstead:"代わりにこちらを保持する →"},howItWorks:{eyebrow:"使い方",title:"3ステップ、決定するまで何も変更されません。",steps:[{num:"01 — スキャン",title:"フォルダー、ドライブ、またはPC全体を選択",body:"Duplicate Finder はすべてのファイルをハッシュ化して、完全に一致するファイルを見つけます — 似た名前やサイズだけで判断しません。"},{num:"02 — 比較",title:"両方のコピーを並べて表示",body:"ファイルサイズ、更新日時、そして画像・PDF・Word文書・Excelシートのライブプレビューを、判断する前に確認できます。"},{num:"03 — 解放",title:"1つを保持し、残りを削除",body:"重複ファイルはごみ箱に移動され、完全に削除されることはありません。いつでも元に戻せます。"}]},features:{eyebrow:"できること",title:"推測ではなく、本当に重複を見つけるために作られています。",items:[{title:"バイト単位での照合",body:"すべてのファイルがハッシュ化されるため、名前や場所が変更されたコピーも検出されます — ファイル名の一致だけに頼りません。"},{title:"ライブプレビュー",body:"画像、PDF、Word文書、Excelシート、コードファイルが、比較画面上で直接表示されます。"},{title:"ごみ箱で安全に削除",body:"すべての削除は Windows 標準のごみ箱を経由します。アプリ自体がファイルを完全に削除することはありません。"},{title:"フォルダーまたはドライブ全体をスキャン",body:"ダウンロードフォルダー1つから C:\\ ドライブ全体まで、お好きな範囲でスキャンできます。"}]},pricing:{amount:"€15",terms:"買い切り \xb7 サブスクリプションなし",list:["14日間、すべての機能を無料で利用可能","体験版にアカウント登録・クレジットカードは不要","1つのライセンスを永続的に所有"],ctaPrimary:"Windows版をダウンロード",ctaSecondary:"ライセンスを購入 →"},faq:{eyebrow:"よくある質問",title:"ダウンロードする前に",items:[{q:"本当に必要なファイルが削除されませんか？",a:"明示的にマークしたファイルのみが、並べて比較した後にのみ削除されます。一致するファイルはファイル内容のハッシュ値によって判定されるため、バイト単位で完全に一致する重複ファイルのみが表示されます。また、削除は常にごみ箱への移動であり、完全な削除ではありません。"},{q:"Mac や Linux でも使えますか？",a:"現時点では対応していません — Duplicate Finder は現在 Windows 専用です。"},{q:"14日間の無料体験が終わるとどうなりますか？",a:"ライセンスキーを入力するまでスキャン機能がロックされます。体験期間中のデータや設定は失われず、キーを有効化すると再びロックが解除されます。"},{q:"インストール時に Windows で警告が表示されるのはなぜですか？",a:"このアプリはまだ有料のコード署名証明書で署名されていないためです。多くの個人開発者は初めての売上を得るまでこのステップを省略します。Windows はソフトウェアの安全性に関わらず、未確認の発行元にはこのように警告を表示します。これはこのアプリ特有の問題ではありません。続行するには「詳細情報」をクリックし、「実行」を選択してください。インストール前に動作を確認したい場合は、ソースコードを GitHub で公開しています。"}]},footer:{copyright:"Duplicate Finder.",changelog:"更新履歴",buy:"購入",privacy:"プライバシー",terms:"利用規約"}},ko:{meta:{title:"Duplicate Finder — Windows에서 중복 파일을 찾아 공간을 확보하세요",description:"모든 폴더나 드라이브를 스캔하고, 실시간 미리보기로 중복 파일을 나란히 비교한 후 안전하게 휴지통으로 이동하세요. 15유로 일회성 구매, 14일 무료 체험."},nav:{howItWorks:"작동 방식",pricing:"가격",faq:"자주 묻는 질문",download:"다운로드"},hero:{eyebrow:"Windows용 \xb7 15유로 일회성 구매 \xb7 14일 무료 체험",headlineLine1:"내",headlineEm:"중복 파일",sub:"모든 폴더나 드라이브를 스캔하여 동일한 파일을 나란히 정확하게 보여주고, 중복 파일을 휴지통으로 이동합니다 — 영구 삭제는 절대 하지 않습니다.",ctaPrimary:"Windows용 다운로드",ctaStore:"Get it from Microsoft Store",ctaSecondary:"작동 방식 보기",ctaNote:"14일간 모든 기능 이용 가능. 계정이나 신용카드가 필요하지 않습니다.",securityNote:'처음 실행 시: Windows에서 "Windows에서 PC를 보호했습니다"라는 메시지가 표시될 수 있습니다 — 독립 개발자의 앱에서는 흔한 일입니다. "추가 정보" → "실행"을 클릭하세요.',demoMeta:"동일한 파일 3개 \xb7 각 158.3 KB",demoReclaimable:"158.3 KB 회수 가능",counterLabel:"이번 스캔에서 회수 가능",cardKeep:"유지",cardDuplicate:"중복",cardMarkForTrash:"휴지통으로 표시",cardOpenFile:"파일 열기 ↗",cardKeepInstead:"대신 이 파일 유지 →"},howItWorks:{eyebrow:"작동 방식",title:"세 단계, 결정하기 전까지는 아무것도 영구적으로 바뀌지 않습니다.",steps:[{num:"01 — 스캔",title:"폴더, 드라이브 또는 전체 PC를 선택하세요",body:"Duplicate Finder는 모든 파일을 해싱하여 정확히 일치하는 항목을 찾습니다 — 단순히 비슷한 이름이나 크기가 아닙니다."},{num:"02 — 비교",title:"두 사본을 나란히 확인하세요",body:"파일 크기, 수정 날짜, 그리고 이미지, PDF, Word 문서, Excel 시트의 실시간 미리보기를 결정하기 전에 확인할 수 있습니다."},{num:"03 — 회수",title:"하나는 유지하고 나머지는 삭제하세요",body:"중복 파일은 휴지통으로 이동하며, 영구 삭제는 절대 하지 않습니다. 언제든지 마음을 바꿀 수 있습니다."}]},features:{eyebrow:"기능",title:"추측이 아니라 실제로 중복 파일을 찾도록 설계되었습니다.",items:[{title:"바이트 단위 비교",body:"모든 파일이 해싱되므로 이름이 바뀌거나 위치가 변경된 사본도 감지됩니다 — 파일명이 일치하는 것만 찾는 것이 아닙니다."},{title:"실시간 미리보기",body:"이미지, PDF, Word 문서, Excel 시트, 코드 파일이 비교 화면에서 바로 표시됩니다."},{title:"휴지통으로 안전하게",body:"모든 삭제는 Windows 자체 휴지통을 거칩니다. 앱 자체가 무언가를 영구적으로 삭제하는 일은 없습니다."},{title:"폴더 또는 드라이브 전체 스캔",body:"다운로드 폴더 하나부터 C:\\ 드라이브 전체까지, 원하는 범위로 스캔할 수 있습니다."}]},pricing:{amount:"€15",terms:"일회성 구매 \xb7 구독 없음",list:["14일간 모든 기능을 무료로 이용","체험판에는 계정이나 신용카드가 필요 없음","하나의 라이선스, 영구 소유"],ctaPrimary:"Windows용 다운로드",ctaSecondary:"라이선스 구매 →"},faq:{eyebrow:"자주 묻는 질문",title:"다운로드하기 전에",items:[{q:"정말 필요한 파일이 삭제되지는 않나요?",a:"명시적으로 표시한 파일만, 그리고 나란히 비교한 후에만 삭제됩니다. 일치 항목은 파일 내용을 해싱하여 찾기 때문에 실제로 바이트 단위까지 동일한 중복 파일만 표시됩니다 — 그리고 모든 삭제는 휴지통으로 이동하며 영구 삭제가 아닙니다."},{q:"Mac이나 Linux에서도 작동하나요?",a:"아직은 아닙니다 — Duplicate Finder는 현재 Windows 전용입니다."},{q:"14일 체험 기간이 끝나면 어떻게 되나요?",a:"라이선스 키를 입력할 때까지 스캔 기능이 잠깁니다. 체험 기간의 데이터와 설정은 영향을 받지 않습니다 — 키를 활성화하면 다시 잠금이 해제됩니다."},{q:"설치할 때 Windows에서 경고가 표시되는 이유는 무엇인가요?",a:'아직 유료 코드 서명 인증서로 서명되지 않았기 때문입니다 — 대부분의 1인 개발자가 첫 판매 전에는 생략하는 단계입니다. Windows는 소프트웨어의 안전 여부와 관계없이 인식되지 않은 게시자에 대해 이렇게 표시합니다. 이 앱만의 문제가 아닙니다. 계속하려면 "추가 정보"를 클릭한 다음 "실행"을 선택하세요. 설치 전에 동작을 확인하고 싶다면 소스 코드가 GitHub에 공개되어 있습니다.'}]},footer:{copyright:"Duplicate Finder.",changelog:"변경 이력",buy:"구매",privacy:"개인정보처리방침",terms:"이용약관"}}};function f(a){return d.some(b=>b.code===a)}}};